const body = $input.first().json.body;
const required = ['topic', 'role'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const difficulty = ['beginner','intermediate','advanced','mixed'].includes(body.difficulty) ? body.difficulty : 'mixed';
const quizType = ['multiple_choice','true_false','short_answer','mixed'].includes(body.quiz_type) ? body.quiz_type : 'multiple_choice';
return [{ json: { valid: true, quizId: `QZ-${Date.now()}`, topic: body.topic.trim(), role: body.role.trim(), companyContext: (body.company_context||'').slice(0,500), sourceContent: (body.source_content||'').slice(0,5000), questionCount: Math.min(20,Math.max(3,parseInt(body.question_count)||10)), difficulty, quizType, passingScore: parseInt(body.passing_score)||70, recipientEmail: body.recipient_email||'', managerEmail: body.manager_email||'', replyEmail: body.reply_email||null, requestedAt: new Date().toISOString() } }];

values.content:
Generate an onboarding quiz.

Topic: {{ $json.topic }}
Role: {{ $json.role }}
Company context: {{ $json.companyContext || 'not provided' }}
Number of questions: {{ $json.questionCount }}
Difficulty: {{ $json.difficulty }}
Quiz type: {{ $json.quizType }}
Passing score: {{ $json.passingScore }}%

Source content:
{{ $json.sourceContent || 'Generate questions based on standard knowledge for this topic and role.' }}

Return this JSON:
{
  "quiz_title": "quiz title",
  "quiz_description": "1-2 sentences on what this quiz covers",
  "estimated_minutes": 10,
  "questions": [
    {
      "id": "Q1",
      "type": "multiple_choice",
      "question": "question text",
      "options": ["A. option", "B. option", "C. option", "D. option"],
      "correct_answer": "A",
      "explanation": "why correct and why wrong options are wrong",
      "difficulty": "beginner",
      "topic_area": "sub-topic"
    }
  ],
  "learning_objectives": ["what a passing employee should understand"],
  "study_resources": ["things to review if struggling"]
}

