const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let quiz;
try { quiz = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Quiz Request').first().json;
quiz._meta = { quizId: input.quizId, topic: input.topic, role: input.role, passingScore: input.passingScore, recipientEmail: input.recipientEmail, managerEmail: input.managerEmail, replyEmail: input.replyEmail, createdAt: new Date().toISOString() };
quiz.questions_for_employee = quiz.questions.map(q => ({ id: q.id, type: q.type, question: q.question, options: q.options, difficulty: q.difficulty, topic_area: q.topic_area }));
return [{ json: quiz }];

const q = $input.first().json;
const m = q._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const questionBlocks = (q.questions_for_employee||[]).map((question, idx) => {
  const optionRows = (question.options||[]).map((opt, oi) => `<div style="display:flex;gap:10px;align-items:center;padding:8px 12px;border:1px solid #e5e7eb;border-radius:6px;margin-bottom:6px"><input type="radio" name="${esc(question.id)}" value="${String.fromCharCode(65+oi)}" id="${esc(question.id)}_${oi}"><label for="${esc(question.id)}_${oi}" style="font-size:14px;cursor:pointer">${esc(opt)}</label></div>`).join('');
  const tfOptions = question.type === 'true_false' ? `<div style="display:flex;gap:12px;margin-top:8px"><label style="display:flex;gap:6px;cursor:pointer"><input type="radio" name="${esc(question.id)}" value="True"> True</label><label style="display:flex;gap:6px;cursor:pointer"><input type="radio" name="${esc(question.id)}" value="False"> False</label></div>` : '';
  const shortAnswer = question.type === 'short_answer' ? `<textarea name="${esc(question.id)}" style="width:100%;border:1px solid #e5e7eb;border-radius:6px;padding:10px;font-size:14px;margin-top:8px;min-height:80px" placeholder="Your answer..."></textarea>` : '';
  return `<div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:18px 20px;margin-bottom:14px"><div style="font-size:12px;color:#9ca3af;margin-bottom:6px">Q${idx+1} · ${esc(question.topic_area||'')} · ${esc(question.difficulty||'')}</div><div style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:12px">${esc(question.question)}</div>${question.type === 'multiple_choice' ? optionRows : ''}${question.type === 'true_false' ? tfOptions : ''}${question.type === 'short_answer' ? shortAnswer : ''}</div>`;
}).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:sans-serif"><div style="max-width:680px;margin:0 auto"><div style="background:#1e293b;color:#fff;padding:20px 24px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;color:#64748b;margin-bottom:5px">Onboarding Quiz · ${esc(m.role)}</div><div style="font-size:18px;font-weight:700">${esc(q.quiz_title)}</div><div style="font-size:13px;color:#94a3b8;margin-top:4px">${q.questions_for_employee.length} questions · ~${q.estimated_minutes||10} min · Passing: ${m.passingScore}%</div></div><div style="background:#eff6ff;padding:14px 24px;border:1px solid #bfdbfe;border-top:none"><p style="font-size:14px;color:#1e3a8a;margin:0">${esc(q.quiz_description)}</p></div><div style="background:#f9fafb;padding:16px 24px;border:1px solid #e5e7eb;border-top:none">${questionBlocks}</div><div style="background:#fff;padding:14px 24px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6;text-align:center;font-size:12px;color:#9ca3af">Quiz ID: ${esc(m.quizId)} · Submit answers via POST to /submit-quiz</div></div></body></html>`;
return [{ json: { html, quizId: m.quizId, quizTitle: q.quiz_title, replyEmail: m.replyEmail, recipientEmail: m.recipientEmail, quiz: q } }];

const body = $input.first().json.body;
const required = ['quiz_id', 'respondent_name', 'your_answers'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
return [{ json: { valid: true, quizId: body.quiz_id, respondentName: body.respondent_name, respondentEmail: body.respondent_email||'', yourAnswers: body.your_answers, submittedAt: new Date().toISOString() } }];

const rows = $('Load Quiz Data').all().map(r => r.json);
const submission = $('Validate Submission').first().json;
const quizRow = rows.find(r => r.quiz_id === submission.quizId);
if (!quizRow) return [{ json: { error: 'Quiz not found' } }];
let questions;
try { questions = JSON.parse(quizRow.quiz_json); } catch(e) { return [{ json: { error: 'Could not parse quiz data' } }]; }
const answers = submission.yourAnswers;
let correct = 0;
const results = questions.map(q => {
  const given = answers[q.id];
  const isCorrect = q.type === 'short_answer' ? (given||'').trim().length > 0 : String(given||'').toUpperCase() === String(q.correct_answer||'').toUpperCase();
  if (isCorrect) correct++;
  return { id: q.id, question: q.question, given_answer: given||'(no answer)', correct_answer: q.correct_answer, is_correct: isCorrect, explanation: q.explanation, topic_area: q.topic_area };
});
const score = questions.length > 0 ? Math.round((correct/questions.length)*100) : 0;
const passed = score >= parseInt(quizRow.passing_score||70);
const byTopic = {};
results.forEach(r => { if (!byTopic[r.topic_area]) byTopic[r.topic_area] = {correct:0,total:0}; byTopic[r.topic_area].total++; if (r.is_correct) byTopic[r.topic_area].correct++; });
return [{ json: { submission, results, score, correct, total: questions.length, passed, passingScore: parseInt(quizRow.passing_score||70), byTopic, quizRow } }];

const d = $input.first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const passColor = d.passed ? '#16a34a' : '#dc2626';
const resultRows = d.results.map(r => `<div style="border:1px solid ${r.is_correct?'#bbf7d0':'#fecaca'};border-radius:6px;margin-bottom:10px;overflow:hidden"><div style="background:${r.is_correct?'#f0fdf4':'#fef2f2'};padding:10px 14px;display:flex;justify-content:space-between;align-items:flex-start"><div style="font-size:14px;font-weight:600;flex:1;margin-right:10px">${esc(r.question)}</div><span style="background:${r.is_correct?'#16a34a':'#dc2626'};color:#fff;font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px;white-space:nowrap">${r.is_correct?'Correct':'Incorrect'}</span></div><div style="padding:10px 14px;font-size:13px"><div><strong>Your answer:</strong> <span style="color:${r.is_correct?'#16a34a':'#dc2626'}">${esc(r.given_answer)}</span></div>${!r.is_correct?`<div><strong>Correct:</strong> <span style="color:#16a34a">${esc(r.correct_answer)}</span></div>`:''}<div style="color:#6b7280;font-style:italic;margin-top:4px">${esc(r.explanation)}</div></div></div>`).join('');
const topicRows = Object.entries(d.byTopic).map(([t,s]) => { const pct = Math.round(s.correct/s.total*100); return `<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #f3f4f6"><span style="font-size:14px">${esc(t)}</span><span style="font-size:14px;font-weight:600;color:${pct>=70?'#16a34a':pct>=50?'#d97706':'#dc2626'}">${s.correct}/${s.total} (${pct}%)</span></div>`; }).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:sans-serif"><div style="max-width:660px;margin:0 auto"><div style="background:#1e293b;color:#fff;padding:18px 24px;border-radius:10px 10px 0 0"><div style="font-size:18px;font-weight:700">${esc(d.submission.respondentName)} — Quiz Results</div></div><div style="background:${d.passed?'#f0fdf4':'#fef2f2'};padding:16px 24px;border:1px solid ${d.passed?'#bbf7d0':'#fecaca'};border-top:none;display:flex;align-items:center;justify-content:space-between"><div><span style="background:${passColor};color:#fff;font-size:14px;font-weight:700;padding:5px 18px;border-radius:14px">${d.passed?'PASSED':'NOT PASSED'}</span><div style="font-size:13px;color:#555;margin-top:6px">Passing score: ${d.passingScore}%</div></div><div style="text-align:right"><div style="font-size:40px;font-weight:800;color:${passColor}">${d.score}%</div><div style="font-size:13px;color:#6b7280">${d.correct} of ${d.total} correct</div></div></div>${topicRows?`<div style="background:#fff;padding:14px 24px;border:1px solid #e5e7eb;border-top:none">${topicRows}</div>`:''}<div style="background:#fff;padding:14px 24px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">${resultRows}</div></div></body></html>`;
return [{ json: { html, respondentEmail: d.submission.respondentEmail, respondentName: d.submission.respondentName, score: d.score, passed: d.passed, quizId: d.submission.quizId, results: d } }];
